import{_ as a,c as t,a0 as s,o as i}from"./chunks/framework.BGabeMLJ.js";const n="/images/ui_images/analysis_start.png",o="/images/ui_images/analysis_distribution.png",y=JSON.parse('{"title":"Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"guide/user/analysis.md","filePath":"guide/user/analysis.md"}'),r={name:"guide/user/analysis.md"};function l(d,e,h,c,u,p){return i(),t("div",null,e[0]||(e[0]=[s('<h1 id="analysis" tabindex="-1">Analysis <a class="header-anchor" href="#analysis" aria-label="Permalink to &quot;Analysis&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Important</p><p>Prerequisites Before creating a new analysis, ensure that at least one proposal has been created within your organization. If not, create a proposal first <a href="./project.html">here</a>.</p></div><h2 id="creating-an-analysis" tabindex="-1">Creating an Analysis <a class="header-anchor" href="#creating-an-analysis" aria-label="Permalink to &quot;Creating an Analysis&quot;">​</a></h2><h3 id="_1-navigate-to-analysis" tabindex="-1">1. Navigate to Analysis <a class="header-anchor" href="#_1-navigate-to-analysis" aria-label="Permalink to &quot;1. Navigate to Analysis&quot;">​</a></h3><p>In the Home section, select <strong>Projects</strong> from the left-hand menu and open the desired project. You&#39;ll arrive at the project&#39;s Overview page; switch to the <strong>Analyses</strong> tab to reach the Outgoing page.</p><h3 id="_2-initiate-creation" tabindex="-1">2. Initiate Creation <a class="header-anchor" href="#_2-initiate-creation" aria-label="Permalink to &quot;2. Initiate Creation&quot;">​</a></h3><p>Click <strong>+ Add</strong> to open the analysis creation form. Here you can optionally provide a <strong>Display Name</strong> and <strong>Description</strong> — a URL-friendly <strong>Name</strong> is generated automatically but can be edited. Click <strong>create</strong> to open the Analysis Wizard, where all other aspects of the analysis are configured. <a href="/images/ui_images/analysis_start.png"><img src="'+n+'" alt="image"></a></p><h3 id="_3-configure-analysis" tabindex="-1">3. Configure Analysis <a class="header-anchor" href="#_3-configure-analysis" aria-label="Permalink to &quot;3. Configure Analysis&quot;">​</a></h3><p>Analysis Wizard — key steps:</p><ul><li>Node Selection: In the <strong>Nodes</strong> tab, choose the nodes the analysis should run on. By default, all nodes available in the project are selected.</li><li>Upload: In the <strong>Code</strong> tab, upload one or more analysis code files — either a single file or an entire directory.</li><li>Image Selection: In the <strong>Image</strong> tab, define the master image group and select the appropriate base image (e.g., Python base, ML, etc.).</li><li>Select Entrypoint: In the <strong>Image</strong> tab, select the file that should serve as the analysis&#39;s entrypoint.</li><li>Lock Configuration: Back on the <strong>Overview</strong> tab, once all requirements are fulfilled, the analysis must be locked to proceed to the next step.</li></ul><h3 id="approval" tabindex="-1">Approval <a class="header-anchor" href="#approval" aria-label="Permalink to &quot;Approval&quot;">​</a></h3><p>Before the analysis can be built and executed, it must be approved by the nodes you selected during setup. Refer to the <a href="./../admin/analysis-review.html">Admin Guide</a> for detailed information on the approval process.</p><h3 id="_4-build-analysis" tabindex="-1">4. Build Analysis <a class="header-anchor" href="#_4-build-analysis" aria-label="Permalink to &quot;4. Build Analysis&quot;">​</a></h3><p>Once all nodes have <a href="#approval">approved</a> the analysis, the <strong>start</strong> button in the <strong>Build</strong> area can be clicked to build the container.</p><h3 id="_5-distribute-analysis" tabindex="-1">5. Distribute Analysis <a class="header-anchor" href="#_5-distribute-analysis" aria-label="Permalink to &quot;5. Distribute Analysis&quot;">​</a></h3><p>To distribute the built analysis across the selected nodes, click the <strong>start</strong> button in the <strong>Distribution</strong> area. <a href="/images/ui_images/analysis_distribution.png"><img src="'+o+'" alt="image"></a></p><h2 id="execution" tabindex="-1">Execution <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;Execution&quot;">​</a></h2><p>Once the analysis has been approved, successfully built, and distributed to the selected nodes, it is ready for execution.</p><p>Each node administrator must manually start the analysis via the node UI. For more details, consult the <a href="./../admin/analysis-execution.html">Node Guide</a>.</p><h2 id="download-results" tabindex="-1">Download Results <a class="header-anchor" href="#download-results" aria-label="Permalink to &quot;Download Results&quot;">​</a></h2><p>Once all nodes have completed the analysis, click the Download button under the <strong>Results</strong> tab to retrieve the result files.</p>',21)]))}const m=a(r,[["render",l]]);export{y as __pageData,m as default};
